import{_ as t,o as s,c as i,a4 as a}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"Compilation Context","description":"#include is textual substitution: what a header means depends on the preprocessor state before the include. The same file can therefore compile to entirely different results — a source file under its…","frontmatter":{"head":[["meta",{"property":"og:title","content":"Compilation Context | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/compilation-context"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/compilation-context"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/compilation-context"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/compilation-context"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/compilation-context"}],["meta",{"property":"og:description","content":"#include is textual substitution: what a header means depends on the preprocessor state before the include. The same file can therefore compile to entirely different results — a source file under its…"}]]},"headers":[],"relativePath":"clice/design/compilation-context.md","filePath":"en/clice/design/compilation-context.md","lastUpdated":1794738697000}'),n={name:"clice/design/compilation-context.md"};function o(r,e,h,c,l,d){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="compilation-context" tabindex="-1">Compilation Context <a class="header-anchor" href="#compilation-context" aria-label="Permalink to &quot;Compilation Context&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p><code>#include</code> is textual substitution: what a header means depends on the preprocessor state before the include. The same file can therefore compile to entirely different results — a source file under its Debug and its Release command, a header under each file that includes it.</p><p>A language server must pick one such context to serve a file, and every answer depends on that pick. Existing servers pick implicitly and give the user no way to see or change the pick; when it is wrong, the user sees a flood of false errors. In clangd this shows as long-standing issues: headers that are not self-contained do not work (<a href="https://github.com/clangd/clangd/issues/45" target="_blank" rel="noreferrer">clangd#45</a>), a header&#39;s command is guessed from file names and often wrong (<a href="https://github.com/clangd/clangd/issues/1505" target="_blank" rel="noreferrer">clangd#1505</a>), and of a file&#39;s several commands the user cannot choose one (<a href="https://github.com/clangd/clangd/issues/681" target="_blank" rel="noreferrer">clangd#681</a>).</p><p>clice makes the compilation context a first-class concept: every compile, index entry and answer knows which context it belongs to, and the user can list the contexts of a file and switch between them.</p><h2 id="what-a-context-is" tabindex="-1">What a Context Is <a class="header-anchor" href="#what-a-context-is" aria-label="Permalink to &quot;What a Context Is&quot;">​</a></h2><p>A compilation context is everything needed to restore a file&#39;s compilation state.</p><ul><li>For a <strong>source file</strong>, it is one of its commands. A file listed several times in the compilation database — Debug and Release, two platforms — has several contexts.</li><li>For a <strong>self-contained header</strong>, one that includes everything it needs, it is the command of a source including it: the header compiles alone under that command&#39;s search paths and language standard.</li><li>For a header that is <strong>not self-contained</strong>, such as an X macro list that only means something after its includer defines <code>X</code>, it is a <strong>header context</strong>: a host source file that includes it, and the position in the host&#39;s include tree where it is included. A header without an include guard can be included several times by one host, each time in another state, so the positions are numbered and a host plus a number names one context.</li></ul><h2 id="choosing-a-context" tabindex="-1">Choosing a Context <a class="header-anchor" href="#choosing-a-context" aria-label="Permalink to &quot;Choosing a Context&quot;">​</a></h2><p>A file compiles in the first of these that applies:</p><ol><li><strong>The user&#39;s choice</strong>, made through <code>clice/switchContext</code> and kept in the project&#39;s cache directory; a header chosen to compile in a host always takes the host&#39;s prefix. A choice that stops holding — its host no longer includes the file, its entry left the database — waits, inactive, and applies again once it holds.</li><li><strong>The file&#39;s own command</strong>, when it is a unit of the build: its entry in a compilation database (of several, the first, until the user picks another), the <code>default_command</code> covering it, or a provisional member&#39;s.</li><li><strong>A host</strong>: a source the build compiles that includes the header, ranked as <a href="./command-resolve#rules-members-and-hosts">Command Resolution</a> describes. A self-contained header takes its command; one that is not takes its command and a synthesized prefix (below).</li><li><strong>A rule&#39;s <code>default_command</code></strong>, for a header no unit hosts.</li><li><strong>A borrowed command</strong>: a nearby unit&#39;s, for a file nothing describes yet — a new source, a header nothing includes (see <a href="./command-resolve#rules-members-and-hosts">Command Resolution</a>).</li><li><strong>clice&#39;s own command</strong>, so an isolated file still gets basic answers.</li></ol><p>The editor reaches this through clice&#39;s requests:</p><table tabindex="0"><thead><tr><th>Request</th><th>What it does</th></tr></thead><tbody><tr><td><code>clice/queryContext</code></td><td>Lists a file&#39;s contexts: a source&#39;s entries, a header&#39;s hosts, best first and paged. Contexts that compile identically are listed once.</td></tr><tr><td><code>clice/currentContext</code></td><td>The context the file compiles in, whether the user chose it, and the command it compiles with and where that command comes from.</td></tr><tr><td><code>clice/switchContext</code></td><td>Picks one of the listed contexts; the file recompiles in it, without being closed.</td></tr><tr><td><code>clice/resetContext</code></td><td>Drops the choice, back to the context clice picks.</td></tr><tr><td><code>clice/showOtherContexts</code></td><td>Whether the code the file&#39;s context skips shows what the file&#39;s other contexts compile there, which the index holds.</td></tr></tbody></table><p>Inside the chosen context, the branches the preprocessor skips are dimmed, so a switch shows at once.</p><h2 id="build-configurations" tabindex="-1">Build Configurations <a class="header-anchor" href="#build-configurations" aria-label="Permalink to &quot;Build Configurations&quot;">​</a></h2><p>A file&#39;s context is chosen per file; a <strong>build configuration</strong> is chosen per project. Rules can carry a <code>configuration</code> tag, the tags form a menu, and one is active in a server: its tagged rules apply, untagged rules always do. It is resolved once at startup from <code>--configuration</code>, the selection persisted from the editor, then <code>default_configuration</code> or the first tag.</p><p>Switching configurations restarts the server, on purpose: a server holds one configuration&#39;s whole world — its databases, dependency graph, contexts and index — and starting into another is the cold start every session performs anyway, warm from that configuration&#39;s own cache. Each configuration has an index database of its own, so switching never mixes two configurations&#39; indexes, and switching back reindexes only what changed on disk meanwhile.</p><h2 id="is-a-header-self-contained" tabindex="-1">Is a Header Self-Contained? <a class="header-anchor" href="#is-a-header-self-contained" aria-label="Permalink to &quot;Is a Header Self-Contained?&quot;">​</a></h2><p>Most headers are, and synthesizing a prefix for them is wasted work. clice tries first: it compiles the header alone under its host&#39;s command. Without errors, the header is self-contained. With errors, it compiles the header once more with the host&#39;s prefix, and the compile with fewer errors stands: fewer in the host&#39;s context makes the header not self-contained, a tie keeps it self-contained. No list of what an includer provides is needed — whatever the context fixes counts. Fragment extensions by convention (<code>.def</code>, <code>.inc</code>, <code>.inl</code>, <code>.tpp</code>, …) skip the check.</p><p>The verdict is kept with the files the check read and holds while they do not change. A change of another file it read runs the check again. The header&#39;s own edits keep it — typing never checks again, or a half-typed name would keep switching it — except that saving a header judged self-contained while its compile has errors checks it again.</p><h2 id="compiling-a-header-in-its-host-s-context" tabindex="-1">Compiling a Header in Its Host&#39;s Context <a class="header-anchor" href="#compiling-a-header-in-its-host-s-context" aria-label="Permalink to &quot;Compiling a Header in Its Host&#39;s Context&quot;">​</a></h2><p>clice compiles the header itself, with a synthesized <strong>prefix</strong> forced in through <code>-include</code>. Following the host&#39;s include tree down to the header, it takes from each file on the way everything before the include of the next one, each piece behind a <code>#line</code> so positions stay those of the original files:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// main.cpp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;vector&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DEBUG</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;utils.h&quot;</span></span></code></pre></div><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// utils.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#pragma</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> once</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;string&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;math.h&quot;</span></span></code></pre></div><p>Opening <code>math.h</code> compiles it with this prefix forced in:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#line</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 1 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main.cpp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;vector&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DEBUG</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#line</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 1 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utils.h&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#pragma</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> once</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;string&gt;</span></span></code></pre></div><p>The prefix exists only in memory, in pieces placed in the directories of the files they were cut from, so every relative lookup inside them resolves as it does in those files. A cut inside <code>#if</code> blocks, such as an include guard, is balanced: the prefix closes them and the suffix reopens them. A header inside braces its includer opens — an enumerator list, a class body — also gets a <strong>suffix</strong> that closes them. Any change to a file on the chain discards the context, and the next compile synthesizes it again.</p><p>The reason for <code>-include</code> is the preamble&#39;s PCH: what is forced in is compiled before the header&#39;s own text, so the whole prefix lands in the header&#39;s PCH, and an edit to the header recompiles only its body.</p><h2 id="contexts-in-the-index" tabindex="-1">Contexts in the Index <a class="header-anchor" href="#contexts-in-the-index" aria-label="Permalink to &quot;Contexts in the Index&quot;">​</a></h2><p>A header&#39;s entries differ from context to context. Its index shard keeps the entries of each context as a variant, and queries take the union of the live variants: references to both branches of a header&#39;s <code>#ifdef</code> are found. See <a href="./symbol-index">Symbol Index</a>.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><p><strong>Is a header compiled through <code>-include</code> the same as in its host?</strong> For everything the standard defines, yes: <code>#line</code> sets what <code>__FILE__</code>, <code>__LINE__</code> and <code>std::source_location</code> say. Two extensions differ: <code>__INCLUDE_LEVEL__</code> is 0, and <code>__BASE_FILE__</code> names the header rather than the host. Neither matters to the answers.</p></li><li><p><strong>Why not compile the host and stop at the end of the header?</strong> It needs no synthesis and keeps the surrounding braces intact, but the header then sits in the middle of the host&#39;s include tree, where no PCH can split. Every edit of the header would parse everything the host includes before it again, which is too slow on a large project. Making the header the compiled file keeps its prefix in a PCH.</p></li></ul><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>A host is tried under one command.</strong> Of a host&#39;s several commands, the first that fits the header is tried; a header only another of them enters is hosted elsewhere, or nowhere.</li><li><strong>An include spelled through a macro cannot be cut</strong> (<code>#include FT_FREETYPE_H</code>): a header entered that way that needs its includer&#39;s state compiles under the host&#39;s command alone.</li><li><strong>A chosen host that includes the header through a macro stops holding when it changes</strong>, until a compile reads its include tree again; choosing the host again restores it.</li><li><strong>Switching a build configuration restarts the server.</strong></li></ul>`,34)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
